// Read the result of the SSH command.
const result = $input.first().json;
const stdout = String(result.stdout ?? "");

// Stop if the Python command failed.
if (Number(result.code) !== 0) {
  throw new Error("The daily news command failed. Check the SSH output.");
}

// End this execution if another daily process is already running.
if (stdout.includes("Another daily_news process is already running")) {
  return [];
}

// Extract the completed run ID.
const match = stdout.match(/Run ID:\s*(\d+)/);

if (!match) {
  throw new Error("No completed run ID was found in the SSH output.");
}

const runId = Number(match[1]);

if (!Number.isSafeInteger(runId) || runId <= 0) {
  throw new Error("The run ID is invalid.");
}

// Pass the run ID to the Postgres node.
return [{ json: { run_id: runId } }];

// Collect all news records from the Postgres node.
const records = $input.all().map(item => item.json);

if (records.length === 0) {
  return [];
}

// Escape text before inserting it into HTML.
function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, character => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[character]);
}

// Use the current date in the workflow's local timezone.
const date = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Europe/Berlin",
  year: "numeric",
  month: "long",
  day: "numeric"
}).format(new Date());

// Create one formatted section for each news record.
const sections = records.map(record => {
  const url = String(record.original_url ?? "").trim();
  const link = /^https?:\/\/[^\s]+$/i.test(url)
    ? `<p><a href="${escapeHtml(url)}">Read the original article</a></p>`
    : "";

  const summary = escapeHtml(record.summary_text)
    .replace(/\r?\n/g, "<br>");

  return `
    <div style="padding:20px 0;border-bottom:1px solid #dddddd;">
      <p style="color:#666666;font-size:13px;">
        ${escapeHtml(record.country)} · ${escapeHtml(record.source)}
      </p>
      <h2 style="font-size:20px;margin:8px 0;">
        ${escapeHtml(record.original_title)}
      </h2>
      <p style="line-height:1.6;">${summary}</p>
      ${link}
    </div>
  `;
}).join("");

// Return one item so the Gmail node sends one combined email.
return [{
  json: {
    run_id: records[0].run_id,
    news_count: records.length,
    subject: `RSS Daily News — ${date}`,
    html: `
      <div style="max-width:720px;margin:auto;padding:24px;
                  font-family:Arial,sans-serif;color:#222222;">
        <h1>RSS Daily News</h1>
        <p style="line-height:1.6;color:#555555;">
          Today’s news from different parts of the world.
          A broader view begins with reading beyond familiar perspectives,
          without having to agree with everything we read.
        </p>
        <p>${escapeHtml(date)} · ${records.length} news items</p>
        ${sections}
      </div>
    `
  }
}];
